// This is a simple interface which specifies echo.Route addition functions which
// are present on both echo.Echo and echo.Group, since we want to allow using
// either of them for path registration
type EchoRouter interface {
	CONNECT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	DELETE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	GET(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	HEAD(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	OPTIONS(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PATCH(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	POST(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	PUT(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
	TRACE(path string, h echo.HandlerFunc, m ...echo.MiddlewareFunc) *echo.Route
}

// RegisterHandlersOptions configures RegisterHandlersWithOptions.
type RegisterHandlersOptions struct {
	// BaseURL is prepended to every registered path so the API can be served
	// under a prefix.
	BaseURL string
	// OperationMiddlewares lets the caller attach per-operation middleware at
	// registration time. The map key is the OpenAPI `operationId` value as it
	// appears in the spec (the raw, un-normalized form). Operations that have
	// no entry are registered with no extra middleware. A nil map disables
	// per-operation middleware entirely.
	OperationMiddlewares map[string][]echo.MiddlewareFunc
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{})
}

// RegisterHandlersWithBaseURL registers handlers and prepends BaseURL to the
// paths so the API can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{BaseURL: baseURL})
}

// RegisterHandlersWithOptions registers handlers using the supplied options,
// including any per-operation middleware.
func RegisterHandlersWithOptions(router EchoRouter, si ServerInterface, options RegisterHandlersOptions) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.POST(options.BaseURL+"/auth/login", wrapper.LoginUser, options.OperationMiddlewares["LoginUser"]...)
	router.GET(options.BaseURL+"/auth/me", wrapper.GetProfile, options.OperationMiddlewares["GetProfile"]...)
	router.POST(options.BaseURL+"/auth/register", wrapper.RegisterUser, options.OperationMiddlewares["RegisterUser"]...)
	router.GET(options.BaseURL+"/suppliers", wrapper.ListSuppliers, options.OperationMiddlewares["ListSuppliers"]...)
	router.POST(options.BaseURL+"/suppliers", wrapper.CreateSupplier, options.OperationMiddlewares["CreateSupplier"]...)
	router.GET(options.BaseURL+"/suppliers/stats", wrapper.GetSupplierStats, options.OperationMiddlewares["GetSupplierStats"]...)
	router.DELETE(options.BaseURL+"/suppliers/:supplierID", wrapper.DeleteSupplier, options.OperationMiddlewares["DeleteSupplier"]...)
	router.GET(options.BaseURL+"/suppliers/:supplierID", wrapper.GetSupplier, options.OperationMiddlewares["GetSupplier"]...)
	router.PUT(options.BaseURL+"/suppliers/:supplierID", wrapper.UpdateSupplier, options.OperationMiddlewares["UpdateSupplier"]...)
	router.GET(options.BaseURL+"/suppliers/:supplierID/addresses", wrapper.GetSupplierAddresses, options.OperationMiddlewares["GetSupplierAddresses"]...)
	router.POST(options.BaseURL+"/suppliers/:supplierID/addresses", wrapper.AddSupplierAddress, options.OperationMiddlewares["AddSupplierAddress"]...)
	router.DELETE(options.BaseURL+"/suppliers/:supplierID/addresses/:addressID", wrapper.DeleteSupplierAddress, options.OperationMiddlewares["DeleteSupplierAddress"]...)
	router.PUT(options.BaseURL+"/suppliers/:supplierID/addresses/:addressID", wrapper.UpdateSupplierAddress, options.OperationMiddlewares["UpdateSupplierAddress"]...)
	router.POST(options.BaseURL+"/suppliers/:supplierID/addresses/:addressID/set-main", wrapper.SetMainSupplierAddress, options.OperationMiddlewares["SetMainSupplierAddress"]...)
	router.POST(options.BaseURL+"/suppliers/:supplierID/block", wrapper.BlockSupplier, options.OperationMiddlewares["BlockSupplier"]...)
	router.GET(options.BaseURL+"/suppliers/:supplierID/contacts", wrapper.GetSupplierContacts, options.OperationMiddlewares["GetSupplierContacts"]...)
	router.POST(options.BaseURL+"/suppliers/:supplierID/contacts", wrapper.AddSupplierContact, options.OperationMiddlewares["AddSupplierContact"]...)
	router.DELETE(options.BaseURL+"/suppliers/:supplierID/contacts/:contactID", wrapper.DeleteSupplierContact, options.OperationMiddlewares["DeleteSupplierContact"]...)
	router.PUT(options.BaseURL+"/suppliers/:supplierID/contacts/:contactID", wrapper.UpdateSupplierContact, options.OperationMiddlewares["UpdateSupplierContact"]...)
	router.POST(options.BaseURL+"/suppliers/:supplierID/contacts/:contactID/set-primary", wrapper.SetPrimarySupplierContact, options.OperationMiddlewares["SetPrimarySupplierContact"]...)
	router.GET(options.BaseURL+"/suppliers/:supplierID/groups", wrapper.GetSupplierGroups, options.OperationMiddlewares["GetSupplierGroups"]...)
	router.POST(options.BaseURL+"/suppliers/:supplierID/groups", wrapper.AddSupplierGroup, options.OperationMiddlewares["AddSupplierGroup"]...)
	router.DELETE(options.BaseURL+"/suppliers/:supplierID/groups/:groupID", wrapper.DeleteSupplierGroup, options.OperationMiddlewares["DeleteSupplierGroup"]...)
	router.PUT(options.BaseURL+"/suppliers/:supplierID/groups/:groupID", wrapper.UpdateSupplierGroup, options.OperationMiddlewares["UpdateSupplierGroup"]...)
	router.GET(options.BaseURL+"/suppliers/:supplierID/materials", wrapper.GetSupplierMaterials, options.OperationMiddlewares["GetSupplierMaterials"]...)
	router.PUT(options.BaseURL+"/suppliers/:supplierID/materials", wrapper.UpdateSupplierMaterials, options.OperationMiddlewares["UpdateSupplierMaterials"]...)
	router.POST(options.BaseURL+"/suppliers/:supplierID/next-stage", wrapper.AdvanceSupplierStage, options.OperationMiddlewares["AdvanceSupplierStage"]...)
	router.GET(options.BaseURL+"/suppliers/:supplierID/ratings", wrapper.GetSupplierRatings, options.OperationMiddlewares["GetSupplierRatings"]...)
	router.POST(options.BaseURL+"/suppliers/:supplierID/ratings", wrapper.AddSupplierRating, options.OperationMiddlewares["AddSupplierRating"]...)
	router.GET(options.BaseURL+"/suppliers/:supplierID/stage-history", wrapper.GetStageHistory, options.OperationMiddlewares["GetStageHistory"]...)
	router.GET(options.BaseURL+"/suppliers/:supplierID/outstandings", wrapper.GetSupplierOutstandings, options.OperationMiddlewares["GetSupplierOutstandings"]...)

}

